"""Seeded generator for the made-up test fixtures (AT 10-16: no real ids, handles, URLs or text).

Usage: python -m tests.fixtures.gen_anon_fixtures [--check]
Rewrites, from the label skeleton already in each fixture (never from the real data/ dumps):
  tests/fixtures/fit_rubric.anon.json  ids in the 9000... range with the same sha256 split parity,
      url https://example.invalid/status/<id>, text/reason/relabel_note newly generated; level, split,
      borderline, prev_level, added_in and the asset claims are kept.
Running it twice gives byte-identical output (fixed SEED). --check exits 1 if a file would change.
raw_decline1_cvprofiles_cards.json (tests/fixtures and web/src/test) get every status id renumbered to 9000...
The other fixtures (discovery_20261013_offtopic.json, seed_score_fixtures.json,
web/src/test/fixtures.json) are invented text written by hand to keep identical Fit/score results; their
handles use the fixture_user_NN pattern and their ids the 9000... range (see FIXTURE_ID_PREFIX).
"""
from __future__ import annotations

import hashlib
import json
import random
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
SEED = 20261016
FIXTURE_ID_PREFIX = "9000000"
RUBRIC_ID_START = 9000000000000100000      # holdout ids use 9000000000000000000..49
HOLDOUT_N = 50
KEEP = ("level", "borderline", "split", "prev_level", "added_in")

TOPICS = ["survey design", "agent models", "cultural samples", "measurement layers", "newsroom checks",
          "policy feedback", "lab methods", "synthetic respondents"]
REASONS = {
    "claim": ["Made-up: takes a clear side on the asset claim about {t}.",
              "Made-up: argues for the claim using a {t} example.",
              "Made-up: argues against the claim with a {t} result."],
    "topic": ["Made-up: discusses {t} but takes no position on the claim.",
              "Made-up: on topic ({t}), no claim the asset answers."],
    "none": ["Made-up: keyword overlap only ({t}); promo or off-field.",
             "Made-up: bot log or crypto post that borrows the words."],
}
NOTE = "Made-up relabel note {n}: re-checked against the current claim; kept per keep-previous rule."


def split_of(sid: str) -> str:
    return "heldout" if int(hashlib.sha256(sid.encode()).hexdigest(), 16) % 2 else "fit"


def gen_rubric(old: dict) -> dict:
    rng = random.Random(SEED)
    out = {k: old[k] for k in ("schema_version", "rubric_version", "created")}
    out["source"] = ("Made-up test fixture generated by tests/fixtures/gen_anon_fixtures.py (seeded). Only the "
                     "label skeleton (level/split/borderline) mirrors the real rubric, which stays on the box.")
    out["levels"] = old["levels"]
    out["holdout"] = {"run_id": "discovery-fixture-holdout", "source": "made-up ids",
                      "status_ids": [str(9000000000000000000 + i) for i in range(HOLDOUT_N)]}
    out["gaps"] = old.get("gaps", [])
    nxt, n = RUBRIC_ID_START, 0
    assets = {}
    for aid, a in old["assets"].items():
        exs = []
        for e in a["examples"]:
            while split_of(str(nxt)) != e["split"]:
                nxt += 1
            sid = str(nxt); nxt += 1; n += 1
            t = rng.choice(TOPICS)
            ne = {"id": sid, "url": f"https://example.invalid/status/{sid}",
                  "text": f"Made-up reference post {n:03d} ({aid}, {e['level']}) about {t}. "
                          f"Token {rng.getrandbits(48):012x}.",
                  "level": e["level"], "reason": rng.choice(REASONS[e["level"]]).format(t=t),
                  "borderline": e["borderline"], "split": e["split"]}
            for k in ("prev_level", "added_in"):
                if k in e:
                    ne[k] = e[k]
            if "added_in" in e:
                ne["source"] = "made-up search"
            if "relabel_note" in e:
                ne["relabel_note"] = NOTE.format(n=n)
            exs.append(ne)
        assets[aid] = {"one_line_claim": a["one_line_claim"], "examples": exs}
    out["assets"] = assets
    out["split_rule"] = old["split_rule"]
    return out


RAW_DECLINE = [HERE / "raw_decline1_cvprofiles_cards.json",
               HERE.parents[1] / "web" / "src" / "test" / "raw_decline1_cvprofiles_cards.json"]
_STATUS = re.compile(r"(/status/)(\d+)")


def gen_ids(text: str, start: int = 9000000000000000700) -> str:
    """Every status id -> a 9000... fixture id, numbered in order of first appearance (idempotent)."""
    seen: dict[str, str] = {}

    def sub(m):
        if m.group(2) not in seen:
            seen[m.group(2)] = str(start + len(seen))
        return m.group(1) + seen[m.group(2)]
    return _STATUS.sub(sub, text)


def outputs() -> dict:
    p = HERE / "fit_rubric.anon.json"
    out = {p: json.dumps(gen_rubric(json.loads(p.read_text())), indent=1, ensure_ascii=False) + "\n"}
    for r in RAW_DECLINE:
        out[r] = gen_ids(r.read_text())
    return out


def main(argv: list[str]) -> int:
    out = outputs()
    if "--check" in argv:
        return 0 if all(p.read_text() == t for p, t in out.items()) else 1
    for p, t in out.items():
        p.write_text(t)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
